    @Transactional
    public SettingValue setClerkLimit(String sheetId, String by, BigDecimal limit, LocalDate from) {
        return record(sheetId, by, "clerk-limit", limit != null ? limit.setScale(2, RoundingMode.UNNECESSARY) : null, from);
    }

