                    kept.add(personId);
                    return null;
                }, sheetId, user);
        Set<Long> watched = new HashSet<>(now);
        then.forEach((personId, on) -> {
            if (on) {
                watched.add(personId);
            } else {
                watched.remove(personId);
            }
        });
        return watched;
    }

